script:
await step('Mở màn hình Lịch sinh phiếu định kỳ Bảo trì (/maintenance/schedule)', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  assert(/\/maintenance\/schedule/.test(page.url()), 'Không vào được trang Lịch sinh phiếu định kỳ Bảo trì');
});

await step('Kiểm tra hiển thị danh sách lịch và bộ lọc', async () => {
  const txt = await page.locator('body').innerText();
  assert(txt.length > 30, 'Trang Lịch sinh phiếu định kỳ không hiển thị dữ liệu');
  ctx.log('Đã tải trang Lịch sinh phiếu định kỳ Bảo trì.');
});
